{
  "template": "trigger"
}

namespace newton;
table Settings { coeffs:[double]; damping:double; tolerance:double; max_iter:ulong; }
table Outputs { settings:Settings (required); }
root_type Outputs;

{
  "template": "input",
  "params": [
    {
      "name": "coeffs",
      "type": "double[]",
      "data": [
        1.0,
        0.0,
        0.0,
        -1.0
      ]
    },
    {
      "name": "damping",
      "type": "double",
      "data": 1.0
    },
    {
      "name": "tolerance",
      "type": "double",
      "data": 1e-12
    },
    {
      "name": "max_iter",
      "type": "uint64",
      "data": 60
    }
  ]
}

namespace newton;
table Problem {
  label:string;
  coeffs:[double];
  roots_re:[double];
  roots_im:[double];
  multiplicity:[ulong];
  critical_re:[double];
  critical_im:[double];
  damping:double;
  tolerance:double;
  max_iter:ulong;
}
table Outputs { problem:Problem (required); }
root_type Outputs;

{ pkgs, inputs, params }:
let
  sdk = inputs.tsugumi.sdk { languages = [ "python" ]; };
in
{
  run = inputs.tsugumi.pythonCard {
    inherit sdk;
    src = ./src;
    packages = ps: [ ps.numpy ];
  };
}

{
  "language": "python",
  "inputs": [
    {
      "name": "settings"
    }
  ]
}

{
  "template": "fork",
  "params": [
    {
      "name": "branches",
      "type": "string[]",
      "data": [
        "orbits",
        "basins",
        "trouble"
      ]
    }
  ]
}

namespace newton;
table Orbits {
  label:string;
  coeffs:[double];
  damping:double;
  start_re:[double];
  start_im:[double];
  root_re:[double];
  root_im:[double];
  multiplicity:[ulong];
  status:string;
  lengths:[ulong];
  errors:[double];
}
table Outputs { errors:Orbits (required); }
root_type Outputs;

